-- Isolated schema fixture from the audited metadata; no live member records.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth; create schema coderdojo; create schema realtime; create schema storage; create schema other_app;
create table auth.users(id uuid primary key,email text,email_confirmed_at timestamptz,is_anonymous boolean default false);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth to authenticated,service_role;
create table realtime.messages(id uuid default gen_random_uuid(),topic text,extension text,payload jsonb); alter table realtime.messages enable row level security; grant usage on schema realtime to authenticated,service_role; grant select,insert on realtime.messages to authenticated,service_role;
create function realtime.send(p_payload jsonb,p_event text,p_topic text,p_private boolean) returns void language sql as $$ insert into realtime.messages(topic,extension,payload) values(p_topic,'broadcast',p_payload) $$;
create table storage.buckets(id text primary key,public boolean); create table storage.objects(id uuid default gen_random_uuid(),bucket_id text,name text); alter table storage.objects enable row level security; grant usage on schema storage to anon,authenticated,service_role; grant select,insert,update,delete on storage.objects to anon,authenticated,service_role;
insert into storage.buckets values('coderdojo',true),('monkeyschool',true);
create table other_app.unchanged(id uuid);
create publication supabase_realtime;
create table coderdojo.badge_categories(id uuid default gen_random_uuid(),deleted boolean default false,category_name text,category_description text,has_image boolean default false,image_revision uuid);
create table coderdojo.badges(id uuid default gen_random_uuid(),deleted boolean default false,achievement text,badge_category_id uuid,description text);
create table coderdojo.belts(id uuid default gen_random_uuid(),deleted boolean default false,color text,hex_code text,description text,sort_order integer);
create table coderdojo.member_attendances(id uuid default gen_random_uuid(),member_id uuid,date date);
create table coderdojo.member_badge_categories(id uuid default gen_random_uuid(),member_id uuid,badge_category_id uuid);
create table coderdojo.member_badges(id uuid default gen_random_uuid(),member_id uuid,badge_id uuid,awarded_by_adult_id uuid,application_notes text,awarded_notes text,rejected_by_adult_id uuid,rejected_notes text,application_date timestamp without time zone,awarded timestamp without time zone,rejected_date timestamp without time zone,goal_date timestamp without time zone);
create table coderdojo.member_belts(id uuid default gen_random_uuid(),member_id uuid,belt_id uuid,awarded_by_adult_id uuid,application_notes text,awarded_notes text,rejected_by_adult_id uuid,rejected_notes text,application_date timestamp without time zone,awarded timestamp without time zone,rejected_date timestamp without time zone);
create table coderdojo.member_parents(id uuid default gen_random_uuid(),member_id uuid,parent_id uuid);
create table coderdojo.members(id uuid default gen_random_uuid(),birth_year integer,deleted boolean default false,email text,fingerprint_id integer,garda_vetted boolean default false,github_login text,goal_long_term text,goal_short_term text,is_mentor boolean default false,is_ninja boolean default false,is_parent boolean default false,login text,login_date timestamp without time zone,login_date_previous timestamp without time zone,name_first text,name_last text,password_hash text,phone text,registered_current_term boolean default false,scratch_name text,team_id uuid,xbox_gamertag text,has_photo boolean default false,has_avatar boolean default false,nfc_tag text);
create table coderdojo.session_pods(id uuid default gen_random_uuid(),session_date date,topic text,mentors_only boolean default false,ends_at timestamp with time zone,url text,host_id uuid,host2_id uuid,deleted boolean default false);
create table coderdojo.sessions(id uuid default gen_random_uuid(),topic text,mentors_only boolean default false,session_date date);
create table coderdojo.teams(id uuid default gen_random_uuid(),deleted boolean default false,goal text,hexcode text,notes text,team_name text,has_image boolean default false,image_revision uuid);
alter table coderdojo.member_belts add constraint member_belts_pkey PRIMARY KEY (id);
alter table coderdojo.teams add constraint teams_pkey PRIMARY KEY (id);
alter table coderdojo.belts add constraint belts_pkey PRIMARY KEY (id);
alter table coderdojo.sessions add constraint sessions_pkey PRIMARY KEY (id);
alter table coderdojo.sessions add constraint sessions_session_date_key UNIQUE (session_date);
alter table coderdojo.members add constraint members_pkey PRIMARY KEY (id);
alter table coderdojo.badges add constraint badges_pkey PRIMARY KEY (id);
alter table coderdojo.member_attendances add constraint member_attendances_member_date_unique UNIQUE (member_id, date);
alter table coderdojo.member_attendances add constraint member_attendances_pkey PRIMARY KEY (id);
alter table coderdojo.member_badge_categories add constraint member_badge_categories_pkey PRIMARY KEY (id);
alter table coderdojo.member_parents add constraint member_parents_pkey PRIMARY KEY (id);
alter table coderdojo.member_badges add constraint member_badges_pkey PRIMARY KEY (id);
alter table coderdojo.badge_categories add constraint badge_categories_pkey PRIMARY KEY (id);
alter table coderdojo.session_pods add constraint session_pods_pkey PRIMARY KEY (id);
alter table coderdojo.member_belts add constraint member_belts_awarded_by_adult_id_fkey FOREIGN KEY (awarded_by_adult_id) REFERENCES coderdojo.members(id) ON DELETE SET NULL;
alter table coderdojo.member_belts add constraint member_belts_belt_id_fkey FOREIGN KEY (belt_id) REFERENCES coderdojo.belts(id) ON DELETE CASCADE;
alter table coderdojo.member_belts add constraint member_belts_member_id_fkey FOREIGN KEY (member_id) REFERENCES coderdojo.members(id) ON DELETE CASCADE;
alter table coderdojo.member_belts add constraint member_belts_rejected_by_adult_id_fkey FOREIGN KEY (rejected_by_adult_id) REFERENCES coderdojo.members(id) ON DELETE SET NULL;
alter table coderdojo.members add constraint members_team_id_fkey FOREIGN KEY (team_id) REFERENCES coderdojo.teams(id) ON DELETE SET NULL;
alter table coderdojo.badges add constraint badges_badge_category_id_fkey FOREIGN KEY (badge_category_id) REFERENCES coderdojo.badge_categories(id) ON DELETE SET NULL;
alter table coderdojo.member_attendances add constraint member_attendances_member_id_fkey FOREIGN KEY (member_id) REFERENCES coderdojo.members(id) ON DELETE CASCADE;
alter table coderdojo.member_badge_categories add constraint member_badge_categories_badge_category_id_fkey FOREIGN KEY (badge_category_id) REFERENCES coderdojo.badge_categories(id) ON DELETE CASCADE;
alter table coderdojo.member_badge_categories add constraint member_badge_categories_member_id_fkey FOREIGN KEY (member_id) REFERENCES coderdojo.members(id) ON DELETE CASCADE;
alter table coderdojo.member_parents add constraint member_parents_member_id_fkey FOREIGN KEY (member_id) REFERENCES coderdojo.members(id) ON DELETE CASCADE;
alter table coderdojo.member_parents add constraint member_parents_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES coderdojo.members(id) ON DELETE CASCADE;
alter table coderdojo.member_badges add constraint member_badges_awarded_by_adult_id_fkey FOREIGN KEY (awarded_by_adult_id) REFERENCES coderdojo.members(id) ON DELETE SET NULL;
alter table coderdojo.member_badges add constraint member_badges_badge_id_fkey FOREIGN KEY (badge_id) REFERENCES coderdojo.badges(id) ON DELETE CASCADE;
alter table coderdojo.member_badges add constraint member_badges_member_id_fkey FOREIGN KEY (member_id) REFERENCES coderdojo.members(id) ON DELETE CASCADE;
alter table coderdojo.member_badges add constraint member_badges_rejected_by_adult_id_fkey FOREIGN KEY (rejected_by_adult_id) REFERENCES coderdojo.members(id) ON DELETE SET NULL;
alter table coderdojo.session_pods add constraint session_pods_host2_id_fkey FOREIGN KEY (host2_id) REFERENCES coderdojo.members(id) ON DELETE SET NULL;
alter table coderdojo.session_pods add constraint session_pods_host_id_fkey FOREIGN KEY (host_id) REFERENCES coderdojo.members(id) ON DELETE SET NULL;
grant usage on schema coderdojo to anon,authenticated,service_role; grant all on all tables in schema coderdojo to anon,authenticated,service_role;
alter publication supabase_realtime add table coderdojo.badge_categories,coderdojo.badges,coderdojo.belts,coderdojo.member_attendances,coderdojo.member_badge_categories,coderdojo.member_badges,coderdojo.member_belts,coderdojo.member_parents,coderdojo.members,coderdojo.session_pods,coderdojo.sessions,coderdojo.teams,other_app.unchanged;
create function coderdojo.can_read_mentor_pods() returns boolean language sql as $$ select true $$;
create function coderdojo.get_attendance_stats() returns bigint language sql as $$ select count(*) from coderdojo.member_attendances $$;
create function realtime.topic() returns text language sql stable as $$ select current_setting('realtime.topic',true) $$;
create function coderdojo.get_attendance_dates() returns table(date text) language sql as $$ select distinct date::text from coderdojo.member_attendances $$;
create function coderdojo.get_attendance_stats_split() returns table(date text,mentor_count bigint,ninja_count bigint,total_count bigint) language sql as $$ select a.date::text,0::bigint,0::bigint,count(*) from coderdojo.member_attendances a group by a.date $$;
